{
  "case_id": "xsu_sg_013_specialist_declaration",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "met", "reason": "Svaret gengiver korrekt, at Udbetaling Danmark i særlige tilfælde kan bede om en speciallægeerklæring, når dokumentationen ikke tilstrækkeligt beskriver art og grad. Alle fire eksempler er korrekt gengivet som illustrative ('for eksempel', 'eller'). Udgiftsdækningen er korrekt. Ingen af de væsentlige fejl fra rubrikken forekommer."},
    "c02_required_elements_complete": {"label": "met", "reason": "Begge kritiske elementer er med: særlige tilfælde og utilstrækkelig beskrivelse af art og grad, samt alle fire eksempelgrupper (symptomstyrke/hyppighed, uoverensstemmelse, stor tvivl om behandling/prognose, stor tvivl om hverdag vs. ferieperioder). Udgiftsbetalingen som supporterende element er også med."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret besvarer direkte, hvornår Udbetaling Danmark kan bede om en speciallægeerklæring, og indeholder ingen irrelevant tekst."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde som lovbestemmelse, vejledningsafsnit eller lignende."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så det kan ikke vurderes, om en kilde understøtter påstandene."},
    "c07_no_unsupported_legal_additions": {"label": "met", "reason": "Alle udsagn kan genfindes i vejledningens afsnit 5.1.3.2. Svaret tilføjer ingen ny regel, betingelse eller myndighed."},
    "c08_qualifications_and_exceptions": {"label": "met", "reason": "'I særlige tilfælde', 'kan' og 'for eksempel' bevarer, at det er en mulighed og at eksemplerne er illustrative. 'Stor tvivl' er bevaret i eksemplerne om behandling/prognose og funktionsniveau. Svaret siger 'stor tvivl om ... funktionsniveau i hverdagen sammenlignet med ferieperioder', og det er semantisk tilstrækkeligt."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Svaret er sammenhængende: først hovedreglen om særlige tilfælde og utilstrækkelig dokumentation, derefter eksempler og udgifter. Konklusionen følger af det anførte."},
    "c10_legal_modality_precision": {"label": "met", "reason": "'Kan' og 'for eksempel' afspejler kilden og gør hverken skøn eller eksempler til absolutte regler. Der er ingen formulering om, at en speciallægeerklæring altid skal indhentes. Formuleringen 'betaler udgifterne' er lidt mere kategorisk end kildens 'eventuelle udgifter', men ændrer ikke betydningen."}
  },
  "xhaile_coverage": {
    "A74": {"label": "yes", "reason": "Svaret dækker, at der i særlige tilfælde kan indhentes en speciallægeerklæring, når dokumentationen ikke tilstrækkeligt beskriver art og grad, og gengiver alle fire eksempler."}
  },
  "overall_notes": "Indholdsmæssigt er svaret korrekt og fuldstændigt. Det angiver dog ingen kilde, så C04 er not_met, og C05 og C06 er not_assessable efter kildereglen."
}

